-- Function: public.fn_get_board_classrooms
-- Backup generated on 2026-10-25 20:33:02

CREATE OR REPLACE FUNCTION public.fn_get_board_classrooms(p_tenant_id uuid, p_org_id uuid, p_date date, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(classroom_id uuid, classroom_name character varying, age_group character varying, branch_id uuid, branch_name character varying, capacity integer, enrolled_children integer, present_children integer, expected_children integer, present_staff integer)  LANGUAGE sql  STABLE AS $function$     SELECT          cl.id AS classroom_id,         cl.name AS classroom_name,         cl.age_group AS age_group,         cl.branch_id AS branch_id,         b.name AS branch_name,         cl.capacity AS capacity,         cl.current_enrollment AS enrolled_children,         COALESCE((             SELECT COUNT(1)::int FROM child_attendance ca             WHERE ca.classroom_id = cl.id AND ca.attendance_date = p_date                AND ca.status IN ('Present', 'Late') AND ca.tenant_id = p_tenant_id         ), 0) AS present_children,         COALESCE((             SELECT COUNT(1)::int FROM children ch             WHERE ch.classroom_id = cl.id AND ch.is_active = true AND ch.tenant_id = p_tenant_id         ), 0) AS expected_children,         COALESCE((             SELECT COUNT(1)::int FROM teacher_attendance ta             WHERE ta.branch_id = cl.branch_id AND ta.attendance_date = p_date               AND ta.status = 'Present' AND ta.tenant_id = p_tenant_id         ), 0) AS present_staff     FROM classrooms cl     JOIN branches b ON cl.branch_id = b.id     WHERE cl.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND cl.is_active = true       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)     ORDER BY b.name, cl.name; $function$ ;
